const NOTIFY_ROLE_NAME = process.env.NOTIFICATION_ROLE_NAME || 'TGS Notifications';
type NotificationMapping={emoji:string;roleId:string;message:string};
const NOTIFICATION_CONFIG_PATH=process.env.NOTIFICATION_CONFIG_PATH||'./data/notification-roles.json';
function loadNotificationMappings():NotificationMapping[]{try{if(!fs.existsSync(NOTIFICATION_CONFIG_PATH))return[];const raw=JSON.parse(fs.readFileSync(NOTIFICATION_CONFIG_PATH,'utf8'));return Array.isArray(raw)?raw.filter((x:any)=>x&&typeof x.emoji==='string'&&typeof x.roleId==='string').map((x:any)=>({emoji:x.emoji,roleId:x.roleId,message:typeof x.message==='string'?x.message:''})):[]}catch{return[]}}
function saveNotificationMappings(m:NotificationMapping[]){fs.mkdirSync(path.dirname(NOTIFICATION_CONFIG_PATH),{recursive:true});fs.writeFileSync(NOTIFICATION_CONFIG_PATH,JSON.stringify(m,null,2),'utf8')}
function roleMention(roleId:string){return '<@&'+roleId+'>'}
const COMMON_EMOJIS=['🔔','📢','📣','🎮','🏆','🎉','📰','🔥','⚡','🚨','🎯','💬','🎁','🛎️','✅'];
function notificationPanel(){const mappings=loadNotificationMappings();const embeds=mappings.slice(0,5).map(m=>new EmbedBuilder().setTitle(m.emoji+' '+(m.message?'Notification Role':'Get Role')).setDescription((m.message||'Click the button below to get this notification role.')+'\\n\\nRole: '+roleMention(m.roleId)).setFooter({text:'Click the emoji button below to get or remove this role.'}));const buttons=mappings.slice(0,5).map(m=>new ButtonBuilder().setCustomId('tgs:notification-role:'+m.roleId).setEmoji(m.emoji).setLabel('Get Role').setStyle(ButtonStyle.Primary));return{embeds:embeds.length?embeds:[new EmbedBuilder().setTitle('🔔 TGS Notifications').setDescription('No notification roles configured.')],components:buttons.length?[new ActionRowBuilder<ButtonBuilder>().addComponents(...buttons)]:[]}}async function handleNotificationButton(i:ButtonInteraction){const guild=i.guild;if(!guild){await i.reply({content:'❌ Server only.',ephemeral:true});return}const roleId=i.customId.split(':')[2];const role=await guild.roles.fetch(roleId).catch(()=>null);if(!role){await i.reply({content:'❌ Role not found.',ephemeral:true});return}const me=guild.members.me||await guild.members.fetchMe();if(role.position>=me.roles.highest.position){await i.reply({content:'❌ Move the bot role above '+roleMention(role.id)+' in Server Settings → Roles.',ephemeral:true});return}const member=await guild.members.fetch(i.user.id);const mapping=loadNotificationMappings().find(m=>m.roleId===role.id);const custom=mapping?.message?.trim();if(member.roles.cache.has(role.id)){await member.roles.remove(role,'TGS notification opt-out');await i.reply({content:(custom||'🔕 Removed '+role.name+'.')+'\n\n🔕 Role removed: '+role.name,ephemeral:true})}else{await member.roles.add(role,'TGS notification opt-in');await i.reply({content:(custom||'🔔 Added '+role.name+'.')+'\n\n🔔 Role added: '+role.name,ephemeral:true})}}
function notificationRoleCommand(){return new SlashCommandBuilder().setName('notification-role').setDescription('Configure custom notification roles').addSubcommand(s=>s.setName('add').setDescription('Choose an emoji and an existing role').addStringOption(o=>o.setName('emoji').setDescription('Choose a notification emoji').setRequired(true).setAutocomplete(true)).addRoleOption(o=>o.setName('role').setDescription('Choose an existing Discord role').setRequired(true)).addStringOption(o=>o.setName('message').setDescription('Custom message shown when the role is added/removed').setRequired(false).setMaxLength(1000))).addSubcommand(s=>s.setName('remove').setDescription('Remove a configured notification role').addStringOption(o=>o.setName('emoji').setDescription('Choose a configured emoji').setRequired(true).setAutocomplete(true))).addSubcommand(s=>s.setName('list').setDescription('List configured notification roles')).toJSON()}
db.exec(`CREATE TABLE IF NOT EXISTS games(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE COLLATE NOCASE,created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS tournaments(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE COLLATE NOCASE,game_id INTEGER,password_hash TEXT,password_salt TEXT,status TEXT NOT NULL DEFAULT 'draft',created_by TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(game_id) REFERENCES games(id));CREATE TABLE IF NOT EXISTS players(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE COLLATE NOCASE,discord_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS tournament_players(tournament_id INTEGER NOT NULL,player_id INTEGER NOT NULL,seed INTEGER,joined_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tournament_id,player_id),FOREIGN KEY(tournament_id) REFERENCES tournaments(id) ON DELETE CASCADE,FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE CASCADE);CREATE TABLE IF NOT EXISTS races(id INTEGER PRIMARY KEY AUTOINCREMENT,tournament_id INTEGER NOT NULL,race_no INTEGER NOT NULL,track TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(tournament_id,race_no),FOREIGN KEY(tournament_id) REFERENCES tournaments(id) ON DELETE CASCADE);CREATE TABLE IF NOT EXISTS results(id INTEGER PRIMARY KEY AUTOINCREMENT,race_id INTEGER NOT NULL,player_id INTEGER NOT NULL,points REAL NOT NULL DEFAULT 0,position INTEGER,kd REAL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(race_id) REFERENCES races(id) ON DELETE CASCADE,FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE CASCADE,UNIQUE(race_id,player_id));CREATE TABLE IF NOT EXISTS matches(id INTEGER PRIMARY KEY AUTOINCREMENT,tournament_id INTEGER NOT NULL,round_no INTEGER NOT NULL DEFAULT 0,round_name TEXT NOT NULL,match_no INTEGER NOT NULL,player1_id INTEGER,player2_id INTEGER,winner_id INTEGER,score1 REAL,score2 REAL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(tournament_id,round_no,match_no),FOREIGN KEY(player1_id) REFERENCES players(id) ON DELETE SET NULL,FOREIGN KEY(player2_id) REFERENCES players(id) ON DELETE SET NULL,FOREIGN KEY(winner_id) REFERENCES players(id) ON DELETE SET NULL);CREATE TABLE IF NOT EXISTS birthdays(discord_id TEXT PRIMARY KEY,month INTEGER NOT NULL,day INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS birthday_config(guild_id TEXT PRIMARY KEY,channel_id TEXT,enabled INTEGER NOT NULL DEFAULT 1,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS birthday_announcements(guild_id TEXT NOT NULL,discord_id TEXT NOT NULL,year INTEGER NOT NULL,announced_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(guild_id,discord_id,year));`);
