function roundName(totalSlots:number,round:number){const totalRounds=Math.log2(totalSlots);if(round===totalRounds)return'Final';if(round===totalRounds-1)return'Semifinal';if(round===totalRounds-2)return'Quarterfinal';return'Round of '+(totalSlots/(2**round))}function createKnockoutFixtures(tournamentId:number,withThird=false){const players=db.prepare('SELECT p.id,p.name,tp.seed FROM tournament_players tp JOIN players p ON p.id=tp.player_id WHERE tp.tournament_id=? ORDER BY CASE WHEN tp.seed IS NULL THEN 1 ELSE 0 END,tp.seed,p.name').all(tournamentId) as any[];if(players.length<2)throw new Error('At least 2 tournament players are required.');const size=2**Math.ceil(Math.log2(players.length)),slots=[...players];while(slots.length<size)slots.push(null as any);db.prepare('DELETE FROM matches WHERE tournament_id=?').run(tournamentId);const totalRounds=Math.log2(size);const tx=db.transaction(()=>{for(let round=1;round<=totalRounds;round++){const count=size/(2**round);for(let m=1;m<=count;m++){const a=round===1?slots[(m-1)*2]:null,b=round===1?slots[(m-1)*2+1]:null,winner=a&&!b?a:!a&&b?b:null,status=winner?'bye':'pending';db.prepare('INSERT INTO matches(tournament_id,round_no,round_name,match_no,player1_id,player2_id,winner_id,status) VALUES(?,?,?,?,?,?,?,?)').run(tournamentId,round,roundName(size,round),m,a?.id??null,b?.id??null,winner?.id??null,status);}}if(withThird&&size>=4){const r=totalRounds;db.prepare('INSERT INTO matches(tournament_id,round_no,round_name,match_no,status) VALUES(?,?,?,?,?)').run(tournamentId,r+1,'3rd Place Decider',1,'pending');}db.prepare("UPDATE tournaments SET status='fixtures_created',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(tournamentId)});tx();return{players:players.length,size}}function createRoundRobinFixtures(tournamentId:number){const players=db.prepare('SELECT p.id,p.name FROM tournament_players tp JOIN players p ON p.id=tp.player_id WHERE tp.tournament_id=? ORDER BY p.name').all(tournamentId) as any[];if(players.length<2)throw new Error('At least 2 tournament players are required.');db.prepare('DELETE FROM matches WHERE tournament_id=?').run(tournamentId);let matchNo=1;const tx=db.transaction(()=>{for(let i=0;i<players.length;i++){for(let j=i+1;j<players.length;j++){db.prepare('INSERT INTO matches(tournament_id,round_no,round_name,match_no,player1_id,player2_id,status) VALUES(?,?,?,?,?,?,?)').run(tournamentId,matchNo,'Round Robin',matchNo,players[i].id,players[j].id,'pending');matchNo++;}}db.prepare("UPDATE tournaments SET status='fixtures_created',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(tournamentId)});tx();return{players:players.length,matches:matchNo-1}}function createLeagueFixtures(tournamentId:number){const players=db.prepare('SELECT p.id,p.name FROM tournament_players tp JOIN players p ON p.id=tp.player_id WHERE tp.tournament_id=? ORDER BY p.name').all(tournamentId) as any[];if(players.length<2)throw new Error('At least 2 tournament players are required.');db.prepare('DELETE FROM matches WHERE tournament_id=?').run(tournamentId);let matchNo=1;const tx=db.transaction(()=>{for(let round=1;round<players.length;round++){for(let i=0;i<Math.floor(players.length/2);i++){const a=players[i],b=players[players.length-1-i];if(!a||!b)continue;db.prepare('INSERT INTO matches(tournament_id,round_no,round_name,match_no,player1_id,player2_id,status) VALUES(?,?,?,?,?,?,?)').run(tournamentId,round,'League Round '+round,matchNo++,a.id,b.id,'pending');}const last=players.pop();if(last)players.splice(1,0,last);}db.prepare("UPDATE tournaments SET status='fixtures_created',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(tournamentId)});tx();return{players:players.length,matches:matchNo-1}}function createFixtures(tournamentId:number,format:string){if(format==='round_robin')return createRoundRobinFixtures(tournamentId);if(format==='league')return createLeagueFixtures(tournamentId);return createKnockoutFixtures(tournamentId,format==='knockout_3rd')} function fixtureText(tournamentId:number){const rows=db.prepare('SELECT m.round_no,m.round_name,m.match_no,p1.name player1,p2.name player2,w.name winner,m.score1,m.score2,m.status FROM matches m LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE m.tournament_id=? ORDER BY m.round_no,m.match_no').all(tournamentId) as any[];if(!rows.length)return'No fixtures.';return rows.map(m=>`**${m.round_name} ${m.match_no}** — ${m.player1||'TBD'} ${m.score1??''} vs ${m.score2??''} ${m.player2||'TBD'} • ${m.status==='completed'?`Winner: **${m.winner}**`:m.status==='bye'?`Bye: **${m.winner}`:'Pending'}`).join('\n')}function syncKnockoutBracket(tournamentId:number){const t=db.prepare('SELECT fixture_format FROM tournaments WHERE id=?').get(tournamentId) as any;if(!t||!['knockout','knockout_3rd'].includes(t.fixture_format||'knockout'))return;const rounds=db.prepare('SELECT DISTINCT round_no FROM matches WHERE tournament_id=? ORDER BY round_no').all(tournamentId) as any[];const allMatches=db.prepare('SELECT * FROM matches WHERE tournament_id=? ORDER BY round_no,match_no').all(tournamentId) as any[];const finalMatch=allMatches.find((m:any)=>String(m.round_name)==='Final');const thirdMatch=allMatches.find((m:any)=>String(m.round_name).includes('3rd Place'));for(const rr of rounds){const round=Number(rr.round_no);const current=db.prepare('SELECT * FROM matches WHERE tournament_id=? AND round_no=? ORDER BY match_no').all(tournamentId,round) as any[];const next=db.prepare('SELECT * FROM matches WHERE tournament_id=? AND round_no=? ORDER BY match_no').all(tournamentId,round+1) as any[];if(!next.length||String(current[0]?.round_name||'')==='Final'||String(current[0]?.round_name||'').includes('3rd Place'))continue;for(const m of current){if(!m.winner_id)continue;const nextIndex=Math.floor((Number(m.match_no)-1)/2);const nm=next[nextIndex];if(!nm)continue;const column=Number(m.match_no)%2===1?'player1_id':'player2_id';if(nm[column]!==m.winner_id)db.prepare('UPDATE matches SET '+column+'=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(m.winner_id,nm.id);}for(const nm of next){const p1=nm.player1_id,p2=nm.player2_id;const status=p1&&p2?'pending':p1||p2?'bye':'pending';const winner=status==='bye'?(p1||p2):null;if(nm.status!=='completed')db.prepare('UPDATE matches SET status=?,winner_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(status,winner,nm.id);}}
if(t.fixture_format==='knockout_3rd'&&thirdMatch&&finalMatch){const semifinalRound=Number(finalMatch.round_no)-1;const semis=db.prepare('SELECT * FROM matches WHERE tournament_id=? AND round_no=? ORDER BY match_no').all(tournamentId,semifinalRound) as any[];for(const sm of semis){if(sm.status!=='completed'||!sm.winner_id)continue;const loser=Number(sm.player1_id)===Number(sm.winner_id)?sm.player2_id:sm.player1_id;if(!loser)continue;const column=Number(sm.match_no)===1?'player1_id':'player2_id';if(thirdMatch[column]!==loser)db.prepare('UPDATE matches SET '+column+'=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(loser,thirdMatch.id);}const p1=db.prepare('SELECT player1_id FROM matches WHERE id=?').get(thirdMatch.id) as any;const p2=db.prepare('SELECT player2_id FROM matches WHERE id=?').get(thirdMatch.id) as any;const status=p1?.player1_id&&p2?.player2_id?'pending':p1?.player1_id||p2?.player2_id?'bye':'pending';const winner=status==='bye'?(p1?.player1_id||p2?.player2_id):null;if(thirdMatch.status!=='completed')db.prepare('UPDATE matches SET status=?,winner_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(status,winner,thirdMatch.id);}}
function autoAdvanceRound(tournamentId:number,round:number,matchNo:number){const t=db.prepare('SELECT fixture_format FROM tournaments WHERE id=?').get(tournamentId) as any;if(!t||!['knockout','knockout_3rd'].includes(t.fixture_format||'knockout'))return null;syncKnockoutBracket(tournamentId);const m=db.prepare('SELECT * FROM matches WHERE tournament_id=? AND round_no=? AND match_no=?').get(tournamentId,round,matchNo) as any;if(!m)return null;if(m.round_name==='Final'){if(t.fixture_format==='knockout_3rd'){const third=db.prepare("SELECT * FROM matches WHERE tournament_id=? AND round_name='3rd Place Decider' AND status!='completed'").get(tournamentId) as any;if(!third)return{final:true};return{final:false}}db.prepare("UPDATE tournaments SET status='completed',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(tournamentId);return{final:true}}if(m.round_name==='3rd Place Decider'){const final=db.prepare("SELECT * FROM matches WHERE tournament_id=? AND round_name='Final' AND status='completed'").get(tournamentId) as any;if(final)db.prepare("UPDATE tournaments SET status='completed',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(tournamentId);return{final:Boolean(final)}}syncKnockoutBracket(tournamentId);return{final:false}}function xmlEscape(v:any){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}function excelAttachment(filename:string,sheets:{name:string,rows:any[]}[]){const rowsXml=(rows:any[])=>{const data=rows.length?rows:[{}],headers=Array.from(new Set(data.flatMap(r=>Object.keys(r||{}))));const head='<Row>'+headers.map(h=>`<Cell ss:StyleID="Header"><Data ss:Type="String">${xmlEscape(h)}</Data></Cell>`).join('')+'</Row>';const body=data.map(r=>'<Row>'+headers.map(h=>{const v=r?.[h],type=typeof v==='number'&&Number.isFinite(v)?'Number':'String';return`<Cell><Data ss:Type="${type}">${xmlEscape(v??'')}</Data></Cell>`}).join('')+'</Row>').join('');return head+body};const xml=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Header"><Font ss:Bold="1"/></Style></Styles>${sheets.map(sh=>`<Worksheet ss:Name="${xmlEscape(sh.name.slice(0,31))}"><Table>${rowsXml(sh.rows)}</Table></Worksheet>`).join('')}</Workbook>`;return new AttachmentBuilder(Buffer.from(xml,'utf8'),{name:filename})}function safeFileName(v:string){return String(v).replace(/[^a-z0-9_-]+/gi,'_').slice(0,80)||'report'}
function tournamentExcel(t:any){
 const participants=db.prepare("SELECT p.id,p.name player,tp.seed,tp.joined_at joined_at FROM tournament_players tp JOIN players p ON p.id=tp.player_id WHERE tp.tournament_id=? ORDER BY p.name").all(t.id) as any[];
 const raceResults=db.prepare("SELECT r.player_id,p.name player,ra.race_no race,ra.track,r.position,r.points,r.created_at recorded_at FROM results r JOIN races ra ON ra.id=r.race_id JOIN players p ON p.id=r.player_id WHERE ra.tournament_id=? ORDER BY ra.race_no,r.position,p.name").all(t.id) as any[];
 const races=db.prepare("SELECT race_no race,track,created_at FROM races WHERE tournament_id=? ORDER BY race_no").all(t.id) as any[];
 const matches=db.prepare("SELECT m.round_no,m.round_name,m.match_no,p1.name player1,p2.name player2,m.score1,m.score2,w.name winner,m.status FROM matches m LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE m.tournament_id=? ORDER BY m.round_no,m.match_no").all(t.id) as any[];
 const standings=participants.map((p:any)=>{
  const rr=raceResults.filter((x:any)=>Number(x.player_id)===Number(p.id));
  const total=rr.reduce((sum:number,x:any)=>sum+Number(x.points||0),0);
  const positions=rr.map((x:any)=>Number(x.position)).filter((x:number)=>Number.isFinite(x));
  return {Player:p.player,TotalPoints:total,Races:rr.length,BestPosition:positions.length?Math.min(...positions):'-',AveragePosition:positions.length?(positions.reduce((a:number,b:number)=>a+b,0)/positions.length).toFixed(2):'-'};
 }).sort((a:any,b:any)=>Number(b.TotalPoints)-Number(a.TotalPoints)||((a.BestPosition==='-'?999:Number(a.BestPosition))-(b.BestPosition==='-'?999:Number(b.BestPosition)))||a.Player.localeCompare(b.Player));
 const finalMatch=db.prepare("SELECT m.round_name,m.match_no,p1.name player1,p2.name player2,w.name winner,m.score1,m.score2,m.status FROM matches m LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE m.tournament_id=? AND m.round_name='Final' ORDER BY m.match_no DESC LIMIT 1").get(t.id) as any;
 const pointWinner=standings.find((x:any)=>Number(x.TotalPoints)>0)||null;
 const tournamentWinner=pointWinner?.Player||finalMatch?.winner||null;
 const winnerReason=pointWinner?'Points Winner — '+Number(pointWinner.TotalPoints||0)+' pts':finalMatch?.winner?'Final Match Winner':'TBD';
 const ranked=standings.map((x:any,i:number)=>({Rank:i+1,...x,Winner:tournamentWinner===x.Player?'YES':''}));
 return excelAttachment("TGS-"+safeFileName(t.name)+"-Report.xls",[
  {name:"Summary",rows:[{Tournament:t.name,Game:t.game_name||"General",Status:t.status,Participants:participants.length,Races:races.length,Matches:matches.length,TournamentWinner:tournamentWinner||"-",WinnerReason:winnerReason,PointsWinner:pointWinner?.Player||"-",WinningPoints:pointWinner?.TotalPoints??0,FinalMatchWinner:finalMatch?.winner||"-"}]},
  {name:"Point Standings",rows:ranked},
  {name:"Player Race Points",rows:raceResults.map((x:any)=>({Player:x.player,Race:x.race,Track:x.track,Position:x.position??"-",Points:x.points}))},
  {name:"Race Results",rows:raceResults},
  {name:"Participants",rows:participants.map((p:any)=>({Player:p.player,Seed:p.seed??"-",JoinedAt:p.joined_at}))},
  {name:"Races",rows:races},
  {name:"Matches",rows:matches},
  {name:"Final Result",rows:[{TournamentWinner:tournamentWinner||"-",WinnerReason:winnerReason,PointsWinner:pointWinner?.Player||"-",WinningPoints:pointWinner?.TotalPoints??0,FinalMatchWinner:finalMatch?.winner||"-",Player1:finalMatch?.player1||"TBD",Score1:finalMatch?.score1??"-",Player2:finalMatch?.player2||"TBD",Score2:finalMatch?.score2??"-"}]}
 ]);
}
function playerExcel(p:any,game?:string|null){const rp=game?[p.id,game]:[p.id],races=db.prepare(`SELECT t.name tournament,g.name game_name,ra.race_no race,ra.track,r.position,r.points,r.kd,ra.created_at recorded_at FROM results r JOIN races ra ON ra.id=r.race_id JOIN tournaments t ON t.id=ra.tournament_id LEFT JOIN games g ON g.id=t.game_id WHERE r.player_id=? ${game?'AND g.name=? COLLATE NOCASE':''} ORDER BY ra.created_at DESC,ra.race_no DESC`).all(...rp) as any[],mp=game?[p.id,p.id,game]:[p.id,p.id],matches=db.prepare(`SELECT t.name tournament,g.name game_name,m.round_no round,m.round_name,m.match_no match,p1.name player1,p2.name player2,m.score1,m.score2,w.name winner,m.status,m.updated_at FROM matches m JOIN tournaments t ON t.id=m.tournament_id LEFT JOIN games g ON g.id=t.game_id LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE (m.player1_id=? OR m.player2_id=?) ${game?'AND g.name=? COLLATE NOCASE':''} ORDER BY m.updated_at DESC,m.round_no DESC,m.match_no DESC`).all(...mp) as any[],wins=matches.filter(m=>m.winner===p.name).length,losses=matches.filter(m=>m.status==='completed'&&m.winner&&m.winner!==p.name).length,total=races.reduce((sum,r)=>sum+Number(r.points||0),0);return excelAttachment(`TGS-${safeFileName(p.name)}-Report.xls`,[{name:'Summary',rows:[{Player:p.name,Game:game||'All Games',TotalRacePoints:total,Races:races.length,Matches:matches.length,MatchWins:wins,MatchLosses:losses}]},{name:'Race History',rows:races},{name:'Match History',rows:matches}])}
function gameExcel(g:any){const tournaments=db.prepare('SELECT t.name tournament,t.status,COUNT(DISTINCT ra.id) races,COUNT(DISTINCT m.id) matches FROM tournaments t LEFT JOIN races ra ON ra.tournament_id=t.id LEFT JOIN matches m ON m.tournament_id=t.id WHERE t.game_id=? GROUP BY t.id ORDER BY t.created_at DESC').all(g.id) as any[],players=db.prepare('SELECT p.name player,COALESCE((SELECT SUM(r.points) FROM results r JOIN races ra ON ra.id=r.race_id JOIN tournaments tt ON tt.id=ra.tournament_id WHERE r.player_id=p.id AND tt.game_id=?),0) points,(SELECT COUNT(*) FROM results r JOIN races ra ON ra.id=r.race_id JOIN tournaments tt ON tt.id=ra.tournament_id WHERE r.player_id=p.id AND tt.game_id=?) races,(SELECT COUNT(*) FROM matches m JOIN tournaments tt ON tt.id=m.tournament_id WHERE (m.player1_id=p.id OR m.player2_id=p.id) AND tt.game_id=?) matches,(SELECT COUNT(*) FROM matches m JOIN tournaments tt ON tt.id=m.tournament_id WHERE m.winner_id=p.id AND tt.game_id=?) match_wins FROM players p WHERE EXISTS(SELECT 1 FROM matches m JOIN tournaments tt ON tt.id=m.tournament_id WHERE (m.player1_id=p.id OR m.player2_id=p.id) AND tt.game_id=?) OR EXISTS(SELECT 1 FROM results r JOIN races ra ON ra.id=r.race_id JOIN tournaments tt ON tt.id=ra.tournament_id WHERE r.player_id=p.id AND tt.game_id=?) ORDER BY points DESC,p.name').all(g.id,g.id,g.id,g.id,g.id,g.id) as any[],matches=db.prepare('SELECT t.name tournament,m.round_no round,m.round_name,m.match_no match,p1.name player1,p2.name player2,m.score1,m.score2,w.name winner,m.status,m.updated_at FROM matches m JOIN tournaments t ON t.id=m.tournament_id LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE t.game_id=? ORDER BY t.created_at DESC,m.round_no,m.match_no').all(g.id) as any[];return excelAttachment(`TGS-${safeFileName(g.name)}-Game-Report.xls`,[{name:'Summary',rows:[{Game:g.name,Tournaments:tournaments.length,Players:players.length,Matches:matches.length}]},{name:'Tournaments',rows:tournaments},{name:'Players',rows:players},{name:'Matches',rows:matches}])}
async function tournamentReport(i:ChatInputCommandInteraction|ButtonInteraction,name:string){
 if(!i.replied&&!i.deferred)await i.deferReply({ephemeral:true});
 try{
  const t=getTournament(name);
  if(!t){await i.editReply('❌ Tournament not found.');return}
  const parts=db.prepare("SELECT p.id,p.name,tp.seed FROM tournament_players tp JOIN players p ON p.id=tp.player_id WHERE tp.tournament_id=? ORDER BY CASE WHEN tp.seed IS NULL THEN 1 ELSE 0 END,tp.seed,p.name").all(t.id) as any[];
  const races=db.prepare("SELECT ra.id,ra.race_no,ra.track,ra.created_at FROM races ra WHERE ra.tournament_id=? ORDER BY ra.race_no").all(t.id) as any[];
  const raceResults=db.prepare("SELECT r.player_id,ra.race_no,ra.track,p.name player,r.position,r.points,r.kd FROM results r JOIN races ra ON ra.id=r.race_id JOIN players p ON p.id=r.player_id WHERE ra.tournament_id=? ORDER BY ra.race_no,r.position,p.name").all(t.id) as any[];
  const matches=db.prepare("SELECT m.round_no,m.round_name,m.match_no,p1.name player1,p2.name player2,w.name winner,m.score1,m.score2,m.status FROM matches m LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE m.tournament_id=? ORDER BY m.round_no,m.match_no").all(t.id) as any[];
  const standings=parts.map((p:any)=>{
   const rr=raceResults.filter((x:any)=>Number(x.player_id)===Number(p.id));
   const total=rr.reduce((sum:number,x:any)=>sum+Number(x.points||0),0);
   const positions=rr.map((x:any)=>Number(x.position)).filter((x:number)=>Number.isFinite(x));
   return {id:p.id,name:p.name,total_points:total,races:rr.length,best_position:positions.length?Math.min(...positions):null,avg_position:positions.length?positions.reduce((a:number,b:number)=>a+b,0)/positions.length:null};
  }).sort((a:any,b:any)=>Number(b.total_points)-Number(a.total_points)||(a.best_position??999)-(b.best_position??999)||a.name.localeCompare(b.name));
  const finalMatch=db.prepare("SELECT m.round_name,m.match_no,p1.name player1,p2.name player2,w.name winner,m.score1,m.score2,m.status FROM matches m LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE m.tournament_id=? AND m.round_name='Final' ORDER BY m.match_no DESC LIMIT 1").get(t.id) as any;
  const hasRacePoints=standings.some((r:any)=>Number(r.total_points||0)>0);
  const pointWinner=hasRacePoints?standings[0]:null;
  const tournamentWinner=pointWinner?.name||finalMatch?.winner||null;
  const winnerReason=pointWinner?'Points Winner — '+Number(pointWinner.total_points||0)+' pts':finalMatch?.winner?'Final Match Winner':'TBD';
  const format=t.fixture_format==='knockout_3rd'?'Knockout + 3rd Place Decider':t.fixture_format==='round_robin'?'Round Robin':t.fixture_format==='league'?'League':'Knockout';
  const statusLabel=String(t.status||'draft').replace(/_/g,' ').replace(/\b\w/g,x=>x.toUpperCase());
  const summary=new EmbedBuilder().setTitle('🏆 '+t.name+' — Tournament Report').addFields(
   {name:'🎮 Game',value:t.game_name||'General',inline:true},
   {name:'⚙️ Format',value:format,inline:true},
   {name:'📌 Status',value:statusLabel,inline:true},
   {name:'🏆 Tournament Winner',value:tournamentWinner?'**'+tournamentWinner+'**\n'+winnerReason:'TBD',inline:true},
   {name:'📊 Points Winner',value:pointWinner?pointWinner.name+' — '+Number(pointWinner.total_points||0)+' pts':'No race points recorded',inline:true},
   {name:'🥇 Final Match Winner',value:finalMatch?.winner||'TBD',inline:true},
   {name:'👥 Participants',value:String(parts.length),inline:true},
   {name:'🏁 Races',value:String(races.length),inline:true},
   {name:'⚔️ Matches',value:String(matches.length),inline:true}
  );
  const participantFields=parts.length?parts.map((p:any,n:number)=>({name:'#'+(n+1)+' '+p.name,value:p.seed!=null?'Seed: #'+p.seed:'Seed: —',inline:true})):[{name:'Participants',value:'No participants recorded.',inline:false}];
  const participantEmbed=new EmbedBuilder().setTitle('👥 Participants').addFields(participantFields.slice(0,25));
  const standingLines=standings.map((r:any,n:number)=>{const rp=races.length?raceResults.filter((x:any)=>Number(x.player_id)===Number(r.id)).map((x:any)=>'R'+x.race_no+': '+x.points+' pts').join(' • ')||'No race points':'No race points';return (n===0&&hasRacePoints?'🏆 ':'')+'**'+(n+1)+'. '+r.name+'** — **'+Number(r.total_points||0)+' pts** • '+r.races+' races • Best P'+(r.best_position??'-')+' • Avg P'+(r.avg_position==null?'-':Number(r.avg_position).toFixed(1))+'\n   '+rp});
  const standingsText=standingLines.length?standingLines.join('\n'):(t.status==='completed'&&tournamentWinner?'🏆 Tournament completed. **'+tournamentWinner+'** is the winner.':'No race results recorded.');
  const standingsEmbed=new EmbedBuilder().setTitle('📊 Point Standings').setDescription(clean(standingsText));
  const fixtureLines=matches.map((m:any)=>'**'+m.round_name+' #'+m.match_no+'** — '+(m.player1||'TBD')+' '+(m.score1??'-')+' - '+(m.score2??'-')+' '+(m.player2||'TBD')+' | '+(m.status==='completed'?'🏆 Winner: **'+(m.winner||'TBD')+'**':m.status==='bye'?'➡️ Bye: **'+(m.winner||'TBD')+'**':'⏳ Pending'));
  const fixtureEmbed=new EmbedBuilder().setTitle('⚔️ Fixture Results').setDescription(clean(fixtureLines.length?fixtureLines.join('\n'):'No fixtures recorded.'));
  const raceLines=raceResults.map((r:any)=>'**Race '+r.race_no+'** — '+r.track+' | P'+(r.position??'-')+' **'+r.player+'** — '+r.points+' pts'+(r.kd!=null?' | KD '+r.kd:''));
  const raceText=raceLines.length?raceLines.join('\n'):(t.status==='completed'&&tournamentWinner?'🏆 Tournament completed. **'+tournamentWinner+'** is the winner.\nNo race points were recorded for this tournament.':'No race results recorded.');
  const raceEmbed=new EmbedBuilder().setTitle('🏁 Race Results').setDescription(clean(raceText));
  await i.editReply({embeds:[summary,participantEmbed,standingsEmbed,fixtureEmbed,raceEmbed]});
  const excel=tournamentExcel(t);
  await i.followUp({content:'📥 **Excel Export — '+t.name+'**\nSame latest tournament report with result/winner details.',files:[excel],ephemeral:true});
 }catch(e:any){
  console.error('Tournament report error:',e);
  if(i.replied||i.deferred)await i.editReply('❌ Could not generate the tournament report. Check the bot console for the exact error.');
  else await i.reply({content:'❌ Could not generate the tournament report. Check the bot console for the exact error.',ephemeral:true});
 }
}
function updateModal(t:any){const m=new ModalBuilder().setCustomId(`tgs:update-form:${t.id}`).setTitle('Update Tournament');m.addComponents(new ActionRowBuilder<TextInputBuilder>().addComponents(new TextInputBuilder().setCustomId('password').setLabel('Tournament password').setStyle(TextInputStyle.Short).setRequired(true).setMinLength(4)),new ActionRowBuilder<TextInputBuilder>().addComponents(new TextInputBuilder().setCustomId('name').setLabel('Tournament name').setStyle(TextInputStyle.Short).setRequired(true).setValue(t.name)),new ActionRowBuilder<TextInputBuilder>().addComponents(new TextInputBuilder().setCustomId('game').setLabel('Game name').setStyle(TextInputStyle.Short).setRequired(true).setValue(t.game_name||'General')),new ActionRowBuilder<TextInputBuilder>().addComponents(new TextInputBuilder().setCustomId('status').setLabel('Status: draft/live/completed').setStyle(TextInputStyle.Short).setRequired(true).setValue(t.status)));return m}async function handleButton(i:ButtonInteraction){const [prefix,action,idText]=i.customId.split(':');if(prefix!=='tgs')return;if(!isManager(i as any)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const id=Number(idText),t=getTournamentById(id);if(!t){await i.reply({content:'❌ Tournament not found.',ephemeral:true});return}if(action==='report'){await tournamentReport(i,t.name);return}if(action==='update'){await i.showModal(updateModal(t));return}if(action==='delete'){await i.showModal(passwordModal('delete',id));return}if(action==='fixtures'){await i.reply({content:`⚙️ **Select Fixture Format for ${t.name}**`,components:[fixtureFormatMenu(id)],ephemeral:true});return}}function tournamentFormatFallback(){return 'knockout'}async function handlePasswordModal(i:ModalSubmitInteraction){const parts=i.customId.split(':'),action=parts[2],format=parts[3]||tournamentFormatFallback(),id=Number(parts[action==='fixtures'?4:3]),t=await passwordOk(i,id);if(!t)return;if(action==='delete'){const deleted=db.transaction(()=>{db.prepare('DELETE FROM matches WHERE tournament_id=?').run(id);db.prepare('DELETE FROM races WHERE tournament_id=?').run(id);db.prepare('DELETE FROM tournaments WHERE id=?').run(id);return true})();await i.reply({content:`🗑️ Tournament **${t.name}** and all its fixtures/results were deleted.`,ephemeral:true});return}if(action==='fixtures'){try{const selectedFormat=format||t.fixture_format||'knockout';db.prepare('UPDATE tournaments SET fixture_format=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(selectedFormat,id);const r=createFixtures(id,selectedFormat);await i.reply({content:`✅ Fixtures created for **${t.name}**.\n⚙️ Format: ${format||t.fixture_format||'knockout'}\n👥 Players: ${r.players}\n📐 Matches: ${r.matches??'bracket'}\n\nUse /fixtures to view them.`,ephemeral:true})}catch(e:any){await i.reply({content:`❌ ${e?.message||'Could not create fixtures.'}`,ephemeral:true})}}}async function handleUpdateForm(i:ModalSubmitInteraction){const id=Number(i.customId.split(':')[2]),t=getTournamentById(id);if(!t){await i.reply({content:'❌ Tournament not found.',ephemeral:true});return}const p=i.fields.getTextInputValue('password');if(!t.password_hash||!t.password_salt||!verifyPassword(p,t.password_hash,t.password_salt)){await i.reply({content:'❌ Incorrect tournament password.',ephemeral:true});return}const name=i.fields.getTextInputValue('name').trim(),gameName=i.fields.getTextInputValue('game').trim(),status=i.fields.getTextInputValue('status').trim().toLowerCase();if(!name){await i.reply({content:'❌ Tournament name cannot be empty.',ephemeral:true});return}const g=getGame(gameName);if(!g){await i.reply({content:`❌ Game **${gameName}** not found.`,ephemeral:true});return}if(!['draft','live','completed','fixtures_created'].includes(status)){await i.reply({content:'❌ Invalid status.',ephemeral:true});return}try{db.prepare('UPDATE tournaments SET name=?,game_id=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(name,g.id,status,id);await i.reply({content:`✅ Tournament updated to **${name}** • 🎮 ${g.name} • ${status}`,ephemeral:true})}catch{await i.reply({content:'❌ Could not update tournament. The name may already exist.',ephemeral:true})}}async function handleSelect(i:StringSelectMenuInteraction){if(i.customId==='tgs:tournament-select'){const id=Number(i.values[0]),t=getTournamentById(id);if(!t){await i.reply({content:'❌ Tournament not found.',ephemeral:true});return}await i.reply({content:`🏆 **${t.name}**\n🎮 ${t.game_name||'General'}\n📌 Status: ${t.status}\n⚙️ Format: ${t.fixture_format||'knockout'}`,components:[managerButtons(id)],ephemeral:true});return}if(i.customId.startsWith('tgs:fixture-format:')){const id=Number(i.customId.split(':')[2]),format=i.values[0],t=getTournamentById(id);if(!t){await i.reply({content:'❌ Tournament not found.',ephemeral:true});return}await i.showModal(passwordModal(`fixtures:${format}`,id));return}}
client.on('interactionCreate',async(i:Interaction)=>{try{if(i.isAutocomplete()){const focused=i.options.getFocused(true),query=String(focused.value??'').trim();if(i.commandName==='notification-role'&&focused.name==='emoji'){const configured=loadNotificationMappings().map(m=>m.emoji);const choices=[...new Set([...COMMON_EMOJIS,...configured])].filter(e=>e.toLowerCase().includes(query.toLowerCase())).slice(0,25);await i.respond(choices.map(e=>({name:e,value:e})));return}if(['tournament','tournament-player','race','match-result','fixtures','tournament-report'].includes(i.commandName)&&focused.name==='tournament'){const rows=db.prepare("SELECT t.name,g.name game_name,t.status FROM tournaments t LEFT JOIN games g ON g.id=t.game_id WHERE t.name LIKE ? COLLATE NOCASE ORDER BY t.created_at DESC LIMIT 25").all(`%${query}%`) as any[];await i.respond(rows.map(t=>({name:`${t.name} • ${t.game_name||'General'} • ${t.status}`.slice(0,100),value:t.name})));return}if(i.commandName==='match-result'&&focused.name==='round'){const tName=i.options.getString('tournament');if(tName){const t0=getTournament(tName);if(t0)syncKnockoutBracket(t0.id);}if(!tName){await i.respond([]);return}const t=getTournament(tName);if(!t){await i.respond([]);return}const rows=db.prepare('SELECT round_no,round_name,COUNT(*) match_count FROM matches WHERE tournament_id=? GROUP BY round_no,round_name ORDER BY round_no').all(t.id) as any[];await i.respond(rows.filter(r=>String(r.round_name).toLowerCase().includes(query.toLowerCase())||String(r.round_no).includes(query)).slice(0,25).map(r=>({name:`Round ${r.round_no} • ${r.round_name} • ${r.match_count} match${r.match_count===1?'':'es'}`.slice(0,100),value:String(r.round_no)})));return}if(i.commandName==='match-result'&&focused.name==='winner'){const tName=i.options.getString('tournament');const roundValue=i.options.getString('round');const matchValue=i.options.getString('match');const t=tName?getTournament(tName):null;const roundNo=roundValue&&/^\d+$/.test(roundValue)?Number(roundValue):null;const matchNo=matchValue&&/^\d+$/.test(matchValue)?Number(matchValue):null;if(!t||!roundNo||!matchNo){await i.respond([]);return}const rows=db.prepare('SELECT p.name FROM matches m JOIN players p ON (p.id=m.player1_id OR p.id=m.player2_id) WHERE m.tournament_id=? AND m.round_no=? AND m.match_no=? AND p.name IS NOT NULL ORDER BY p.name ASC LIMIT 25').all(t.id,roundNo,matchNo) as any[];const choices=rows.filter(p=>String(p.name).toLowerCase().includes(query.toLowerCase())).map(p=>({name:String(p.name).slice(0,100),value:String(p.name)}));await i.respond(choices);return}if(i.commandName==='match-result'&&focused.name==='match'){const tName=i.options.getString('tournament');const roundValue=i.options.getString('round');const t=tName?getTournament(tName):null;const roundNo=roundValue&&/^\d+$/.test(roundValue)?Number(roundValue):null;if(!t||!roundNo){await i.respond([]);return}const rows=db.prepare('SELECT m.match_no,p1.name player1,p2.name player2 FROM matches m LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id WHERE m.tournament_id=? AND m.round_no=? AND m.status IN (\'pending\',\'bye\') ORDER BY m.match_no').all(t.id,roundNo) as any[];await i.respond(rows.filter(m=>m.player1||m.player2).slice(0,25).map(m=>({name:`Match ${m.match_no} • ${m.player1||'TBD'} vs ${m.player2||'TBD'}`.slice(0,100),value:String(m.match_no)})));return}if(['tournament-player','player-report','player-history'].includes(i.commandName)&&focused.name==='player'){let rows:any[]=[];if(i.commandName==='match-result'){const tName=i.options.getString('tournament');const roundValue=i.options.getString('round');const matchValue=i.options.getString('match');const t=tName?getTournament(tName):null;const roundNo=roundValue&&/^\d+$/.test(roundValue)?Number(roundValue):null;const matchNo=matchValue&&/^\d+$/.test(matchValue)?Number(matchValue):null;if(t&&roundNo&&matchNo){rows=db.prepare('SELECT p.name FROM matches m JOIN players p ON (p.id=m.player1_id OR p.id=m.player2_id) WHERE m.tournament_id=? AND m.round_no=? AND m.match_no=? ORDER BY p.name ASC LIMIT 25').all(t.id,roundNo,matchNo) as any[];}}else{rows=db.prepare("SELECT name FROM players WHERE name LIKE ? COLLATE NOCASE ORDER BY name ASC LIMIT 25").all(`%${query}%`) as any[]}await i.respond(rows.filter(p=>String(p.name||'').toLowerCase().includes(query.toLowerCase())).map(p=>({name:p.name,value:p.name})));return}if(['tournament','tournaments','player-report','player-history','game-report'].includes(i.commandName)&&focused.name==='game'){const rows=db.prepare("SELECT name FROM games WHERE name LIKE ? COLLATE NOCASE ORDER BY name ASC LIMIT 25").all(`%${query}%`) as any[];await i.respond(rows.map(g=>({name:g.name,value:g.name})));return}return}if(i.isChatInputCommand())await handleCommand(i);else if(i.isStringSelectMenu())await handleSelect(i);else if(i.isButton()){if(i.customId.startsWith('tgs:notification-role:'))await handleNotificationButton(i);else await handleButton(i);}else if(i.isModalSubmit()&&i.customId.startsWith('tgs:password:'))await handlePasswordModal(i);else if(i.isModalSubmit()&&i.customId.startsWith('tgs:update-form:'))await handleUpdateForm(i)}catch(e:any){console.error('Interaction error:',e);const msg='❌ Something went wrong while processing this action.';if(i.isRepliable()){if(i.replied||i.deferred)await i.followUp({content:msg,ephemeral:true}).catch(()=>{});else await i.reply({content:msg,ephemeral:true}).catch(()=>{})}}});registerCommands().catch(console.error);client.once('ready',()=>{console.log(`Logged in as ${client.user?.tag}`)});client.login(token!);
